/usr/bin/bash -lc "python - <<'PY'
import csv,re
terms=['Tomahawk','Kharg','Malaysia','United Arab Emirates','UAE','Ishaq Dar','Turkiye','Egypt','Caruana','Candidates','MQ-9','Reaper','reinsurance','insurance','Bessent','Sri Lanka','fuel crisis','Hormuz','Prince Sultan','F-15E','F/A-18','Ghalibaf','Araghchi']
rows=list(csv.DictReader(open('market.csv', newline='')))
for term in terms:
    hits=[]
    for r in rows:
        text=' '.join(r.get(k,'') or '' for k in ['title','background','resolution_criteria','my_prediction'])
        if re.search(re.escape(term), text, re.I):
            hits.append((r['qid'],r['resolution_date'],r['title'],r['my_prediction']))
    if hits:
        print('\\nTERM',term,'hits',len(hits))
        for qid,date,title,pred in hits[:12]:
            print(date,qid,title,'|',pred)
PY"

